SELECT p.subject_id, p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, s.stay_id, s.los, d.diagnosis_id, d.diagnosis_code, d.diagnosis_name, u.procedure_id, u.procedure_code, u.procedure_name, rank() OVER (PARTITION BY p.subject_id, s.stay_id ORDER BY u.procedure_id) AS procedure_rank, percentile_cont(0.25) OVER (PARTITION BY p.subject_id, s.stay_id ORDER BY u.procedure_id) AS p25, percentile_cont(0.75) OVER (PARTITION BY p.subject_id, s.stay_id ORDER BY u.procedure_id) AS p75 FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays s ON a.subject_id = s.subject_id AND a.hadm_id = s.stay_id JOIN procedures_icd u ON u.subject_id = p.subject_id AND u.hadm_id = a.hadm_id AND u.chartdate BETWEEN s.intime AND s.outtime JOIN diagnoses_icd d ON d.subject_id = p.subject_id AND d.hadm_id = a.hadm_id AND d.diagnosis_date BETWEEN s.intime AND s.outtime WHERE p.gender = 'M' AND p.anchor_age BETWEEN 39 AND 49 AND s.los BETWEEN 1 AND 7 AND u.procedure_code IN ('US', 'ECHO') AND d.diagnosis_code IN ('ACS', 'ACS2') ORDER BY p.subject_id, s.stay_id, procedure_rank NULLS LAST;